// minimal ESM shim of partial-json (parseIncompleteJSON equivalent used by pi-ai)
export function parse(text, allowPartial = 255) {
  try { return JSON.parse(text); } catch (e) { try { return _splitJson(text); } catch (e2) { return null; } }
}
function _splitJson(s) {
  // attempt graceful closing of open quote/array/object
  const stack=[]; let inStr=false, esc=false;
  for (const c of s) {
    if (inStr) { if (esc) { esc=false; continue; } if (c === '\"') { esc=true; } else if (c === '\"') { inStr=false; } else if (c==='"') { inStr=false; } }
    else if (c==='"') inStr=true;
    else if (c==='['||c==='{') stack.push(c);
    else if (c===']' && stack[stack.length-1]==='[') stack.pop();
    else if (c==='}' && stack[stack.length-1]==='{') stack.pop();
  }
  let t=s; if (inStr) t+='"'; return JSON.parse(t + stack.map(x=>(x==='['?']':'}')).reverse().join(""));
}
